def mod_inverse(a, b):
    """
    Calculate the modular multiplicative inverse of `a` modulo `b` using the
    Extended Euclidean Algorithm.

    Returns the integer `x` such that (a * x) % b == 1 if it exists;
    otherwise returns None.  The function handles improper inputs by
    validating that `a` and `b` are integers and that `b` is a positive
    integer greater than 1.

    Args:
        a (int): The integer whose modular inverse is to be found.
        b (int): The modulus with respect to which the inverse is sought.

    Returns:
        int or None: The modular inverse of `a` modulo `b` if it exists,
        otherwise None.
    """
    # Basic input validation
    try:
        a = int(a)
        b = int(b)
    except (TypeError, ValueError):
        return None

    if b <= 0 or b == 1:
        return None

    # Extended Euclidean Algorithm
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, u, v = extended_gcd(y, x % y)
            return (g, v, u - (x // y) * v)

    gcd_val, x_coeff, _ = extended_gcd(a, b)

    if gcd_val != 1:
        return None

    # Ensure the inverse is in the range [0, b-1]
    inverse = x_coeff % b
    return inverse

